question.solution:
import heapq

def topo_smallest(graph):
    indegree = {u: 0 for u in graph}
    for u in graph:
        for v in graph[u]:
            indegree[v] = indegree.get(v, 0) + 1
    heap = [u for u in graph if indegree[u] == 0]
    heapq.heapify(heap)
    order = []
    while heap:
        u = heapq.heappop(heap)
        order.append(u)
        for v in graph[u]:
            indegree[v] -= 1
            if indegree[v] == 0:
                heapq.heappush(heap, v)
    if len(order) != len(graph):
        return []
    return order

print(topo_smallest({'a': ['b', 'c'], 'b': ['d'], 'c': ['d'], 'd': []}))
print(topo_smallest({'a': ['b'], 'b': ['a']}))
print(topo_smallest({}))
print(topo_smallest({'b': [], 'a': []}))

